self
                .entries
                .iter()
                .filter(|e| {
                    let name = e.name.to_lowercase();
                    let desc = e.description.to_lowercase();
                    name.contains(&q) || desc.contains(&q)
                }).collect

before_inst
            .keys()
            .filter(|k| after_inst.contains_key(*k))
            .filter_map(|k| {
                let b = before_inst[k];
                let a = after_inst[*k];
                let mut changes = HashMap::new();
                if (b.x - a.x).abs() > 1e-6 || (b.y - a.y).abs() > 1e-6 {
                    changes.insert(
                        "position".to_string(),
                        ParamChange {
                            old: format!("({},{})", b.x, b.y),
                            new: format!("({},{})", a.x, a.y),
                        },
                    );
                }
                if b.orient != a.orient {
                    changes.insert(
                        "orient".to_string(),
                        ParamChange {
                            old: b.orient.clone(),
                            new: a.orient.clone(),
                        },
                    );
                }
                if !changes.is_empty() {
                    Some(InstanceModify {
                        name: k.to_string(),
                        changes,
                    })
                } else {
                    None
                }
            }).collect

inst_val
            .as_array()
            .ok_or_else(|| crate::error::VirtuosoError::Execution("instances not an array".into()))?
            .iter()
            .filter_map(|v| {
                let name = v["name"].as_str()?;
                let master = v["master"].as_str()?;
                let (lib_cell, _view_name) = master.split_once('/')?;
                let (lib, cell) = lib_cell.rsplit_once('/').unwrap_or((lib, cell));
                Some(InstanceSnapshot {
                    name: name.to_string(),
                    lib: lib.to_string(),
                    cell: cell.to_string(),
                    x: v["x"].as_f64().unwrap_or(0.0),
                    y: v["y"].as_f64().unwrap_or(0.0),
                    orient: v
                        .get("orient")
                        .and_then(|o| o.as_str())
                        .unwrap_or("R0")
                        .to_string(),
                    params: HashMap::new(),
                })
            }).collect
